package com.nexushr.service; import com.nexushr.dto.EmployeeDtos.*; import com.nexushr.entity.*; import com.nexushr.repository.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class EmployeeService { final EmployeeRepository employees; final UserRepository users; final PasswordEncoder encoder; public EmployeeService(EmployeeRepository e,UserRepository u,PasswordEncoder p){employees=e;users=u;encoder=p;} public List<EmployeeView> all(){return employees.findAll().stream().map(this::view).toList();} public EmployeeView one(UUID id){return view(employees.findById(id).orElseThrow());} @Transactional public EmployeeView create(CreateEmployee x){if(users.findByEmailIgnoreCase(x.email()).isPresent())throw new IllegalArgumentException("Email exists");var u=new User();u.setEmail(x.email().toLowerCase());u.setPasswordHash(encoder.encode(x.password()));u.setRole(Role.valueOf(x.role()==null?"EMPLOYEE":x.role().toUpperCase()));users.save(u);var e=new Employee();e.setUser(u);e.setEmployeeCode(x.employeeCode());e.setFirstName(x.firstName());e.setLastName(x.lastName());e.setPhone(x.phone());e.setDepartment(x.department());e.setDesignation(x.designation());e.setManagerName(x.managerName());e.setJoiningDate(x.joiningDate());e.setBasicSalary(x.basicSalary()==null?java.math.BigDecimal.ZERO:x.basicSalary());return view(employees.save(e));} @Transactional public EmployeeView update(UUID id,UpdateEmployee x){var e=employees.findById(id).orElseThrow(); if(x.firstName()!=null)e.setFirstName(x.firstName());if(x.lastName()!=null)e.setLastName(x.lastName());if(x.phone()!=null)e.setPhone(x.phone());if(x.department()!=null)e.setDepartment(x.department());if(x.designation()!=null)e.setDesignation(x.designation());if(x.managerName()!=null)e.setManagerName(x.managerName());if(x.joiningDate()!=null)e.setJoiningDate(x.joiningDate());if(x.dateOfBirth()!=null)e.setDateOfBirth(x.dateOfBirth());if(x.address()!=null)e.setAddress(x.address());if(x.emergencyContact()!=null)e.setEmergencyContact(x.emergencyContact());if(x.basicSalary()!=null)e.setBasicSalary(x.basicSalary());if(x.onboardingComplete()!=null)e.setOnboardingComplete(x.onboardingComplete());return view(employees.save(e));} public Employee current(String email){return users.findByEmailIgnoreCase(email).flatMap(u->employees.findByUserId(u.getId())).orElseThrow();} private EmployeeView view(Employee e){return new EmployeeView(e.getId(),e.getEmployeeCode(),e.getUser().getEmail(),e.getFirstName(),e.getLastName(),e.getPhone(),e.getDepartment(),e.getDesignation(),e.getManagerName(),e.getJoiningDate(),e.getBasicSalary(),e.getUser().getRole().name(),e.isOnboardingComplete());}}
